return ['domain'=>'tag-groups','plural-forms'=>'nplurals=2; plural=n != 1 && n != 2 && n != 3 && (n % 10 == 4 || n % 10 == 6 || n % 10 == 9);','language'=>'fil','project-id-version'=>'Tag Groups 2.1.2','pot-creation-date'=>'2026-06-15T12:41:40+00:00','po-revision-date'=>'2026-06-17 15:08+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['Tag Groups'=>'Tag-Groups','https://wordpress.org/plugins/tag-groups/'=>'https://wordpress.org/plugins/tag-groups/','Tag Groups allows you to organize your WordPress taxonomy terms and show them in clouds, tabs, accordions, tables, lists and much more.'=>'Ang Tag-Groups ay nagbibigay-daan sa iyo na ayusin ang iyong mga termino sa taxonomy ng WordPress at ipakita ang mga ito sa mga ulap, tab, accordion, talahanayan, listahan at marami pang iba.','TaxoPress'=>'TaxoPress','https://taxopress.com'=>'https://taxopress.com','Home'=>'Bahay','Taxonomies'=>'Taxonomies','Front End'=>'Front End','Back End'=>'Back End','First Steps'=>'Unang Hakbang','Setup Wizard'=>'Setup Wizard','Settings'=>'Mga Setting','Tag Group Admin'=>'Tag Group Admin','The term has been removed from all groups.'=>'Ang termino ay tinanggal mula sa lahat ng grupo.','Edit this item inline'=>'I-edit ang item na ito nang inline','Quick&nbsp;Edit'=>'Mabilis&nbsp;I-edit','Please <a %s>click here to run the migration routines</a> to make sure we have migrated all tags.'=>'Mangyaring <a %s>mag-click dito upang patakbuhin ang mga migration routine</a> upang matiyak na nailipat na natin ang lahat ng mga tag.','Your settings/groups and your terms have been exported. Please download the resulting files with right-click or ctrl-click:'=>'Ang iyong mga setting/grupo at ang iyong mga termino ay na-export na. Mangyaring i-download ang mga resulta ng mga file sa pamamagitan ng right-click o ctrl-click:','Writing of the exported settings failed.'=>'Nabigo ang pagsulat ng mga na-export na setting.','The groups have been sorted alphabetically.'=>'Ang mga grupo ay na-uri ayon sa alpabeto.','The label cannot be empty.'=>'Ang label ay hindi maaaring walang laman.','A tag group with the label \'%s\' already exists, or the label has not changed. Please choose another one or go back.'=>'Mayroon nang tag group na may label na \'%s\', o hindi nagbago ang label. Mangyaring pumili ng iba o bumalik.','A new tag group with the label \'%s\' has been created!'=>'Isang bagong tag group na may label na \'%s\' ang nalikha!','A tag group with the label \'%s\' already exists.'=>'Mayroon nang tag group na may label na \'%s\'.','The tag group with the label \'%s\' has been saved!'=>'Ang tag group na may label na \'%s\' ay nasave na!','A tag group with the id %1$s and the label \'%2$s\' has been deleted.'=>'Isang tag group na may id %1$s at label na \'%2$s\' ang nabura na.','Error uploading the file.'=>'Error sa pag-upload ng file.','Error reading the file.'=>'Error sa pagbabasa ng file.','Error parsing the file.'=>'Error sa pag-parse ng file.','date unknown'=>'petsa ay hindi alam','Your settings and groups have been imported from the file %1$s (created with plugin version %2$s on %3$s).'=>'Ang iyong mga setting at grupo ay na-import mula sa file %1$s (nalikha gamit ang bersyon ng plugin %2$s noong %3$s).','%d option was added or changed.'=>'%d opsyon ang nadagdag o binago.' . "\0" . '%d mga opsyon ang nadagdag o binago.','Your terms have been imported from the file %1$s (created with plugin version %2$s on %3$s).'=>'Ang iyong mga termino ay na-import mula sa file %1$s (nalikha gamit ang bersyon ng plugin %2$s noong %3$s).','We processed %d term.'=>'Naprocess namin ang %d termino.' . "\0" . 'Naprocess namin ang %d mga termino.','We saved %d term.'=>'Naisave namin ang %d termino.' . "\0" . 'Naisave namin ang %d mga termino.','The group info of %d term was updated.'=>'Na-update ang info ng grupo ng %d termino.' . "\0" . 'Na-update ang info ng grupo ng %d mga termino.','Filters'=>'Mga filter','Gutenberg'=>'Gutenberg','Multilingual'=>'Maraming wika','Shortcodes'=>'Mga shortcode','Themes and Appearance'=>'Mga Tema at Hitsura','remove'=>'alisin','(recommended)'=>'(inirerekomenda)','keep'=>'panatilihin','use unfiltered_html filter'=>'gamitin ang unfiltered_html na filter','First Aid'=>'Unang Tulong','REST API'=>'REST API','System Information'=>'Impormasyon ng Sistema','Debugging'=>'Pag-debug','Export/Import'=>'I-export/I-import','Reset'=>'I-reset','Licences'=>'Mga Lisensya','Transients'=>'Mga Transient','Database'=>'Database','Filesystem'=>'Filesystem','WP Object Cache'=>'WP Object Cache','Your settings have been saved.'=>'Ang iyong mga setting ay nai-save na.','Your settings has been saved.'=>'Ang iyong mga setting ay nai-save na.','All groups have been deleted and assignments reset.'=>'Lahat ng grupo ay natanggal at ang mga assignment ay na-reset.','The filter on the tags page has been reset to show all tags.'=>'Ang filter sa pahina ng mga tag ay na-reset upang ipakita ang lahat ng tag.','tag groups'=>'tag groups','tag cloud'=>'tag cloud','group info'=>'group info','sidebar widget'=>'sidebar widget','accordion'=>'accordion','tabs'=>'tabs','alphabetical'=>'alphabetical','post list'=>'post list','colors'=>'colors','tag description'=>'tag description','tag filter'=>'tag filter','post filter'=>'post filter','backup'=>'backup','remove plugin'=>'remove plugin','remove data'=>'remove data','delete groups'=>'delete groups','debugging'=>'debugging','PHP Version'=>'PHP Version','Ajax Test'=>'Ajax Test','troubleshooting'=>'troubleshooting','benchmarks'=>'mga benchmark','speed test'=>'pagsubok sa bilis','error'=>'error','testing'=>'pagsubok','help'=>'tulong','Tag Groups Pro'=>'Tag Groups Pro','upgrade'=>'pag-upgrade','more groups'=>'mas maraming grupo','posts'=>'mga post','filter'=>'filter','animated'=>'animated','searchable'=>'mahanap','Info'=>'Impormasyon','author'=>'may-akda','version'=>'bersyon','contact'=>'kontak','about'=>'tungkol','Licenses'=>'Mga Lisensya','Credits'=>'Mga Kredito','Development News'=>'Balita sa Pag-unlad','blog'=>'blog','updates'=>'mga update','getting started'=>'pagsisimula','introduction'=>'panimula','sample'=>'halimbawa','migrate'=>'ililipat','problem'=>'problema','live block preview'=>'live block preview','translation'=>'pagsasalin','Migrating the term meta'=>'Paglipat ng term meta','Fixing incorrect tag groups'=>'Pag-aayos ng maling grupo ng tag','Fixing incorrect groups in term meta'=>'Pag-aayos ng maling grupo sa term meta','Sorting groups in term meta'=>'Pag-uri-uri ng mga grupo sa term meta','Checking the tag names'=>'Suriin ang mga pangalan ng tag','Start'=>'Simulan','Sample Content'=>'Halimbawa ng Nilalaman','Sample Group A'=>'Halimbawa ng Grupo A','Sample Group B'=>'Halimbawa ng Grupo B','Sample Group C'=>'Halimbawa ng Grupo C','First Sample Tag'=>'Unang Halimbawa ng Tag','Second Sample Tag'=>'Pangalawang Halimbawa na Tag','Third Sample Tag'=>'Pangatlong Halimbawa na Tag','Create a draft sample page with Gutenberg blocks.'=>'Gumawa ng isang draft na sample na pahina gamit ang mga Gutenberg blocks.','Create a draft sample page with shortcodes.'=>'Gumawa ng isang draft na sample na pahina gamit ang mga shortcodes.','The plugin %1$s requires WordPress %2$s to function properly.'=>'Ang plugin %1$s ay nangangailangan ng WordPress %2$s upang gumana ng maayos.','Please upgrade WordPress and then try again.'=>'Mangyaring i-upgrade ang WordPress at subukan muli.','not assigned'=>'hindi nakatalaga','You\'re using Tag Groups Free. The Pro version has more features and support. %1$sUpgrade to Pro%2$s'=>'Gumagamit ka ng Tag Groups Free. Ang Pro na bersyon ay may higit pang mga tampok at suporta. %1$sMag-upgrade sa Pro%2$s','Upgrade to Pro'=>'I-upgrade sa Pro','Upgrade to Tag Groups Pro'=>'I-upgrade sa Tag Groups Pro','Enhance the power of Tag Groups with the Pro version:'=>'Palakasin ang kapangyarihan ng Tag Groups gamit ang Pro version:','21 Shortcodes'=>'21 Shortcodes','18 Gutenberg Blocks'=>'18 Gutenberg Blocks','Table Tag Cloud'=>'Table Tag Cloud','Simple Tag Cloud'=>'Simple Tag Cloud','Shuffle Box'=>'Shuffle Box','Caching'=>'Caching','Multiple Groups Per Tag'=>'Maramihang Mga Grupo Bawat Tag','Tag Cloud Search'=>'Tag Cloud Search','Toggle Post Filter'=>'I-toggle ang Post Filter','Dynamic Post Filter'=>'Dinamiko na Post Filter','Post List'=>'Listahan ng Post','Tag Meta Box'=>'Tag Meta Box','Post Tags in Groups'=>'Post Tags sa Mga Grupo','Permissions'=>'Mga Pahintulot','Default Groups'=>'Mga Default na Grupo','WooCommerce Attributes'=>'Mga Katangian ng WooCommerce','Parent Group Level'=>'Antas ng Parent Group','Need Tag Groups Support?'=>'Kailangan ng Suporta para sa Tag Groups?','If you need help or have a new feature request, let us know.'=>'Kung kailangan mo ng tulong o may bagong kahilingan para sa tampok, ipaalam sa amin.','Request Support'=>'Humiling ng Suporta','Detailed documentation is also available on the plugin website.'=>'Detalyadong dokumentasyon ay available din sa website ng plugin.','View Knowledge Base'=>'Tingnan ang Knowledge Base','The free Tag Groups plugin cannot be active together with Tag Groups Pro.'=>'Ang libreng Tag Groups plugin ay hindi maaaring aktibo kasabay ng Tag Groups Pro.','more information'=>'karagdagang impormasyon','Edit tag groups'=>'I-edit ang mga tag group','Clicking will leave this page without saving.'=>'Ang pag-click ay iiwan ang pahinang ito nang walang pag-save.','Welcome to %s!'=>'Maligayang pagdating sa %s!','The plugin is ready for use. If you need some assistance, we can walk you through the basic steps.'=>'Ang plugin ay handa na para sa paggamit. Kung kailangan mo ng tulong, maaari naming ipakita sa iyo ang mga pangunahing hakbang.','Start the Setup Wizard'=>'Simulan ang Setup Wizard','Or click here if you prefer to do it on your own.'=>'O kaya, mag-click dito kung mas gusto mong gawin ito sa iyong sariling paraan.','Go to the <span class="dashicons dashicons-tag"></span>&nbsp;Tag Groups <a %s>taxonomy settings</a> and <b>select the taxonomy</b> (tag type) of your tags. In most cases just leave the default: Tags (post_tag).'=>'Pumunta sa <span class="dashicons dashicons-tag"></span>&nbsp;Mga Setting ng Tag Groups <a %s>taxonomy</a> at <b>pumili ng taxonomy</b> (uri ng tag) ng iyong mga tag. Sa karamihan ng mga kaso, iwanan lamang ang default: Tags (post_tag).','Go to the tag groups admin page and <b>create some groups</b>.'=>'Pumunta sa pahina ng admin ng mga tag groups at <b>lumikha ng ilang grupo</b>.','You can find these pages listed on your <a %s>Tag Groups home page</a>.'=>'Maaari mong makita ang mga pahinang ito na nakalista sa iyong <a %s>Pahina ng Tahanan ng Tag Groups</a>.','Go to your tags and <b>assign them to these groups</b>.'=>'Pumunta sa iyong mga tag at <b>italaga ang mga ito sa mga grupong ito</b>.','Filter by tag group'=>'I-filter ayon sa grupo ng tag','%s created this sample page in the Setup Wizard of the <b>Tag Groups</b> plugin. You can safely edit and delete it or keep it for future reference.'=>'%s ang lumikha ng sample na pahinang ito sa Setup Wizard ng <b>Tag Groups</b> plugin. Maaari mo itong ligtas na i-edit at i-delete o itago ito para sa hinaharap na sanggunian.','The following shortcodes use a variety of parameters so that you can get an idea of the options. Feel free to generate a new sample page with more features after upgrading the plugin.'=>'Ang mga sumusunod na shortcodes ay gumagamit ng iba\'t ibang mga parameter upang makakuha ka ng ideya sa mga opsyon. Huwag mag-atubiling bumuo ng isang bagong sample na pahina na may higit pang mga tampok matapos i-upgrade ang plugin.','Please find links to the documentation in the <a %s>Tag Groups settings</a>.'=>'Mangyaring hanapin ang mga link sa dokumentasyon sa <a %s>Mga Setting ng Tag Groups</a>.','Tabbed Tag Cloud'=>'Tabbed Tag Cloud','Accordion Tag Cloud'=>'Accordion Tag Cloud','Alphabetical Tag Cloud'=>'Alphabetical Tag Cloud','Tag List'=>'Listahan ng Tag','Alphabetical Tag Index'=>'Alphabetical Tag Index','The following blocks use a variety of parameters so that you can get an idea of the options. Feel free to generate a new sample page with more features after upgrading the plugin.'=>'Ang mga sumusunod na bloke ay gumagamit ng iba\'t ibang mga parameter upang makakuha ka ng ideya sa mga opsyon. Huwag mag-atubiling bumuo ng isang bagong sample na pahina na may higit pang mga tampok matapos i-upgrade ang plugin.','This page was created while you had the Gutenberg editor enabled. Therefore the features only display while Gutenberg is active.'=>'Ang pahinang ito ay nilikha habang nakabukas ang Gutenberg editor. Samakatuwid, ang mga tampok ay nagpapakita lamang habang aktibo ang Gutenberg.','Display filter on the "Posts" screen.'=>'I-display ang filter sa screen ng "Mga Post".','Add a pull-down menu to the filters above the list of posts. If you filter posts by tag groups, then only items will be shown that have tags (terms) in that particular group. This feature can be turned off so that the menu won\'t obstruct your screen if you use a high number of groups. May not work with all taxonomies.'=>'Magdagdag ng pull-down menu sa mga filter sa itaas ng listahan ng mga post. Kung i-filter mo ang mga post ayon sa mga grupo ng tag, tanging ang mga item na may mga tag (mga termino) sa partikular na grupong iyon ang ipapakita. Maaaring i-off ang tampok na ito upang hindi hadlangan ng menu ang iyong screen kung gumagamit ka ng mataas na bilang ng mga grupo. Maaaring hindi ito gumana sa lahat ng taxonomy.','Display filter on the "Tags" screen.'=>'I-display ang filter sa screen ng "Mga Tag".','Add a filter to the list of tags. Disable it here if it conflicts with other plugins or themes.'=>'Magdagdag ng filter sa listahan ng mga tag. I-disable ito dito kung may conflict ito sa ibang plugins o tema.','Save Settings'=>'I-save ang Mga Setting','Gutenberg block preview'=>'preview ng Gutenberg block','Some blocks can show an approximate preview in the Gutenberg editor. If you deactivate this option, then all blocks will show a static icon with text.'=>'Ang ilang mga block ay maaaring ipakita ang isang tinatayang preview sa Gutenberg editor. Kung i-deactivate mo ang opsyong ito, lahat ng block ay magpapakita ng isang static na icon na may teksto.','Keep groups of translations in sync'=>'Panatilihing naka-sync ang mga grupo ng pagsasalin','If you activate this option, we try to sync the groups across all language versions of a tag when you save it. Deactivate it to set groups independently.'=>'Kung i-activate mo ang opsyong ito, susubukan naming i-sync ang mga grupo sa lahat ng bersyon ng wika ng isang tag kapag ito ay sine-save. I-deactivate ito upang i-set ang mga grupo nang hiwalay.','All Tag Groups features are available as Gutenberg blocks. You can also use shortcodes.'=>'Lahat ng mga tampok ng Tag Groups ay available bilang mga Gutenberg block. Maaari mo ring gamitin ang mga shortcode.','Click on the features for more information.'=>'I-click ang mga tampok para sa karagdagang impormasyon.','Display the tags in a tabbed tag cloud.'=>'Ipakita ang mga tag sa isang tabbed tag cloud.','Example'=>'Halimbawa','Parameters'=>'Mga Parameter','Please find the parameters in the <a %s>documentation</a>.'=>'Pakihanap ang mga parameter sa <a %s>dokumento</a>.','Accordion'=>'Accordion','Display the tags in an accordion.'=>'Ipakita ang mga tag sa isang accordion.','Display the tags in lists under tag groups.'=>'Ipakita ang mga tag sa mga listahan sa ilalim ng mga grupo ng tag.','Display the tags in tabbed tag cloud with first letters as tabs.'=>'Ipakita ang mga tag sa tabbed tag cloud na may mga unang titik bilang mga tab.','(Not tested with right-to-left languages.)'=>'(Hindi nasubukan sa mga wika mula kanang bahagi patungo sa kaliwa.)','Display the tags in a list with first letters as heading.'=>'Ipakita ang mga tag sa isang listahan na may mga unang titik bilang pamagat.','Group Information'=>'Impormasyon ng Grupo','Display information about tag groups.'=>'Ipakita ang impormasyon tungkol sa mga grupo ng tag.','The function <b>tag_groups_cloud</b> accepts the same parameters as the [tag_groups_cloud] shortcode, except for those that determine tabs and styling.'=>'Ang function na <b>tag_groups_cloud</b> ay tumatanggap ng parehong mga parameter tulad ng [tag_groups_cloud] shortcode, maliban sa mga iyon na nagtatakda ng mga tab at istilo.','By default it returns a string with the html for a tabbed tag cloud.'=>'Sa default, ito ay nagbabalik ng isang string na may html para sa isang tabbed tag cloud.','If the optional second parameter is set to \'true\', the function returns a multidimensional array containing tag groups and tags.'=>'Kung ang opsyonal na pangalawang parameter ay itinatakda sa \'true\', ang function ay nagbabalik ng isang multidimensional na array na naglalaman ng mga Tag-Groups at mga tag.','Enable shortcode in sidebar widgets (if not visible anyway).'=>'I-enable ang shortcode sa sidebar widgets (kung hindi ito nakikita sa anumang paraan).','Always load shortcode scripts.'=>'Palaging i-load ang mga shortcode scripts.','Click for more information'=>'I-click para sa karagdagang impormasyon','Turn off to load the scripts only on posts and pages where a shortcode appears.'=>'I-off upang i-load ang mga scripts lamang sa mga post at pahina kung saan lumilitaw ang shortcode.','Turn on if you use these shortcodes in widgets.'=>'I-on kung gumagamit ka ng mga shortcode na ito sa widgets.','Here you can choose a theme for the Tabbed Tag Cloud and the Accordion Tag Cloud.'=>'Dito maaari kang pumili ng tema para sa Tabbed Tag Cloud at ang Accordion Tag Cloud.','New themes can be created with the <a href="http://jqueryui.com/themeroller/" target="_blank">jQuery UI ThemeRoller</a>:'=>'Ang mga bagong tema ay maaaring malikha gamit ang <a href="http://jqueryui.com/themeroller/" target="_blank">jQuery UI ThemeRoller</a>:','On the page "Theme Roller" you can customize all features or pick one set from the gallery. Finish with the "download" button.'=>'Sa pahinang "Theme Roller" maaari mong i-customize ang lahat ng mga tampok o pumili ng isang set mula sa gallery. Tapusin gamit ang "download" na button.','On the next page ("Download Builder") you will need to select the version 1.12.x and the components "Widget", "Accordion" and "Tabs". Make sure that before downloading you enter at the bottom as "CSS Scope" <b>.tag-groups-cloud</b> (including the dot).'=>'Sa susunod na pahina ("Download Builder") kailangan mong piliin ang bersyon 1.12.x at ang mga component na "Widget", "Accordion" at "Tabs". Siguraduhin na bago mag-download ay ilagay mo sa ibaba bilang "CSS Scope" <b>.tag-groups-cloud</b> (kasama ang tuldok).','Then you unpack the downloaded zip file. You will need the "images" folder and the "jquery-ui.theme.min.css" file.'=>'Pagkatapos ay i-unpack ang na-download na zip file. Kailangan mo ang "images" na folder at ang "jquery-ui.theme.min.css" na file.','Create a new folder inside your <i>wp-content/uploads</i> folder (for example "my-theme") and copy there these two items.'=>'Gumawa ng bagong folder sa loob ng iyong <i>wp-content/uploads</i> folder (halimbawa "my-theme") at kopyahin dito ang dalawang item na ito.','Enter the name of this new folder (for example "my-theme") below.'=>'I-enter ang pangalan ng bagong folder na ito (halimbawa "my-theme") sa ibaba.','own theme'=>'sariling tema','Don\'t load a theme.'=>'Huwag mag-load ng tema.','Here you can turn off jQuery UI themes if your WordPress theme brings its own jQuery UI theme, in order to avoid conflicts.'=>'Dito maaari mong i-off ang jQuery UI themes kung ang iyong WordPress theme ay nagdadala ng sarili nitong jQuery UI theme, upang maiwasan ang mga conflict.','Further options'=>'Karagdagang mga opsyon','Use jQuery.  (Default is on. Other plugins might override this setting.)'=>'Gumamit ng jQuery. (Ang default ay naka-on. Maaaring i-override ng ibang plugins ang setting na ito.)','Tabs triggered by hovering mouse pointer (without clicking).'=>'Mga Tabs na na-trigger sa pag-hover ng mouse pointer (nang walang pag-click).','Collapsible tabs (toggle open/close).'=>'Mga nababaligtad na tab (buksan/sarado).','HTML in tag description:'=>'HTML sa paglalarawan ng tag:','By default the description appears in a tooltip when you hover the mouse over a tag in a tag cloud.'=>'Sa default, lumalabas ang paglalarawan sa isang tooltip kapag inii-hover mo ang mouse sa isang tag sa tag cloud.','If you don\'t trust all users of your site, remove the HTML or use a plugin to give the unfiltered_html capability only to users you trust.'=>'Kung hindi mo pinagkakatiwalaan ang lahat ng gumagamit ng iyong site, alisin ang HTML o gumamit ng plugin upang bigyan ng unfiltered_html na kakayahan ang mga gumagamit na pinagkakatiwalaan mo lamang.','Save Theme Options'=>'I-save ang Mga Opsyon sa Tema','Search for settings'=>'Hanapin ang mga setting','Search for setting pages. Type a space to show all settings.'=>'Hanapin ang mga pahina ng setting. Mag-type ng space upang ipakita ang lahat ng mga setting.','Search Results'=>'Mga Resulta ng Paghahanap','Nothing found'=>'Walang nahanap','Active Taxonomies'=>'Mga Aktibong Taxonomies','Group Statistics'=>'Estadistika ng Grupo','for the selected language'=>'para sa napiling wika','go to tag group administration'=>'pumunta sa administrasyon ng grupo ng tag','Enable Tag Groups Public API Access'=>'I-enable ang Public API Access ng Tag Groups','Enable public access to tag groups endpoint /wp-json/tag-groups/v1/groups/.'=>'I-enable ang pampublikong access sa endpoint ng tag groups /wp-json/tag-groups/v1/groups/.','Enable Terms Public API Access'=>'I-enable ang Public API Access ng Terms','Enable public access to terms endpoint /wp-json/tag-groups/v1/terms/.'=>'I-enable ang pampublikong access sa endpoint ng terms /wp-json/tag-groups/v1/terms/.','Choose the taxonomies for which you want to use Tag Groups:'=>'Pumili ng mga taxonomies na nais mong gamitin para sa Tag Groups:','The default texonomy is <b>Tags (post_tag)</b>. Please note that the tag clouds might not work with all taxonomies and that some taxonomies listed here may not be accessible in the admin backend. If you don\'t understand what is going on here, just leave the default.'=>'Ang default na taxonomy ay <b>Tags (post_tag)</b>. Pakitandaan na maaaring hindi gumana ang mga tag cloud sa lahat ng taxonomies at na ang ilang taxonomies na nakalista dito ay maaaring hindi ma-access sa admin backend. Kung hindi mo naiintindihan kung ano ang nangyayari dito, iwanan lamang ang default.','<b>Please deselect taxonomies that you don\'t use. Using several taxonomies for the same post type or hierarchical taxonomies (like categories) is experimental and not supported.</b>'=>'<b>Paki-alis ng pagpili sa mga taxonomies na hindi mo ginagamit. Ang paggamit ng maraming taxonomies para sa parehong post type o hierarchical taxonomies (tulad ng mga kategorya) ay experimental at hindi suportado.</b>','To see the post type, hover your mouse over the option.'=>'Upang makita ang post type, i-hover ang iyong mouse sa opsyon.','If you use a custom taxonomy, make sure that the attribute "Public" is set to "true" and "Hierarchical" to "false".'=>'Kung gumagamit ka ng custom taxonomy, tiyakin na ang katangiang "Public" ay nakaset sa "true" at "Hierarchical" sa "false".','Show hierarchical taxonomies. Not all Tag Groups features will work with these taxonomies.'=>'Ipakita ang hierarchical taxonomies. Hindi lahat ng tampok ng Tag Groups ay gagana sa mga taxonomies na ito.','Save Taxonomies'=>'I-save ang Taxonomies','Export'=>'I-export','Use this button to export all Tag Groups settings and groups and all terms that are assigned to a group into files.'=>'Gamitin ang button na ito upang i-export ang lahat ng mga setting ng Tag Groups at mga grupo at lahat ng mga termino na naitalaga sa isang grupo sa mga file.','You can import both files separately. Category hierarchy won\'t be saved. When you restore terms that were deleted, they receive new IDs and you must assign them to posts again. Exporting cannot substitute a backup.'=>'Maaari mong i-import ang parehong mga file nang hiwalay. Ang hierarchy ng kategorya ay hindi masisave. Kapag naibalik mo ang mga terminong na-delete, tumatanggap sila ng mga bagong ID at kailangan mong italaga muli ang mga ito sa mga post. Ang pag-export ay hindi maaaring maging kapalit ng backup.','Export Files'=>'I-export ang mga File','Import'=>'I-import','Below you can import previously exported settings/groups or terms from a file.'=>'Sa ibaba maaari mong i-import ang mga naunang na-export na mga setting/grupo o mga termino mula sa isang file.','It is recommended to back up the database of your site before proceeding.'=>'Inirerekomenda na i-back up ang database ng iyong site bago magpatuloy.','Please import the settings before the terms.'=>'Mangyaring i-import ang mga setting bago ang mga termino.','Import File'=>'I-import ang File','Use this button to delete all tag groups and assignments. Your tags will not be changed. Check the checkbox to confirm.'=>'Gamitin ang button na ito upang tanggalin ang lahat ng mga tag groups at mga asignasyon. Ang iyong mga tag ay hindi mababago. Suriin ang checkbox upang kumpirmahin.','Please keep in mind that the tag assignments cannot be recovered by the export/import function.'=>'Mangyaring isaalang-alang na ang mga tag assignments ay hindi maibabalik sa pamamagitan ng pag-export/pag-import na function.','I know what I am doing.'=>'Alam ko kung ano ang aking ginagawa.','Delete Groups'=>'Tanggalin ang Mga Grupo','Delete Settings and Groups'=>'Tanggalin ang Mga Setting at Grupo','Delete all groups and settings when uninstalling the plugin.'=>'Tanggalin ang lahat ng mga grupo at setting kapag inaalis ang plugin.','Debug mode is on.'=>'Naka-on ang debug mode.','Verbose logging is enabled with CM_DEBUG.'=>'Ang verbose logging ay enabled sa CM_DEBUG.','Verbose logging is on.'=>'Ang verbose logging ay on.','Turn off '=>'Patayin ang ','Verbose logging is off.'=>'Ang verbose logging ay off.','Turn on'=>'Buksan','Debug mode is off.'=>'Ang debug mode ay off.','Learn more <a %s>about debugging</a>.'=>'Matuto pa <a %s>tungkol sa debugging</a>.','Migrate tags to the new format of Tag Groups.'=>'I-migrate ang mga tag sa bagong format ng Tag Groups.','The plugin automatically migrates tags to the new format and tries to keep track of changes. There may, however, be cases where other components made unnoticed changes. You might also need to manually migrate tags after you enabled a taxonomy that already contained untracked tags.'=>'Awtomatikong ini-migrate ng plugin ang mga tag sa bagong format at sinusubukang subaybayan ang mga pagbabago. Gayunpaman, maaaring may mga kaso kung saan ang ibang mga bahagi ay gumawa ng hindi napansin na mga pagbabago. Maaaring kailanganin mo ring manu-manong i-migrate ang mga tag pagkatapos mong i-enable ang isang taxonomy na mayroon nang mga untracked na tag.','Migrate'=>'I-migrate','Running the maintenance can solve issues that you encounter during filtering by tag groups.'=>'Ang pagpapatakbo ng maintenance ay makakapag-solve ng mga isyu na iyong nararanasan sa pag-filter sa pamamagitan ng mga tag groups.','Maintenance'=>'Maintenance','Reset the filter on the tags page to show all tags.'=>'I-reset ang filter sa pahina ng mga tag upang ipakita ang lahat ng mga tag.','Use it if a JavaScript error disables the filter menu. Note that it is still recommended to find out the cause of the error.'=>'Gamitin ito kung ang isang JavaScript error ay nag-disable sa filter menu. Tandaan na inirerekomenda pa ring alamin ang sanhi ng error.','Reset Tag Filter'=>'I-reset ang Tag Filter','Please stay on this page until all processes have finished.'=>'Mangyaring manatili sa pahinang ito hanggang sa matapos ang lahat ng proseso.','There have been errors.'=>'May mga error na nangyari.','Continue'=>'Magpatuloy','Finished!'=>'Tapos na!','The following terms cannot be used:'=>'Ang mga sumusunod na termino ay hindi maaaring gamitin:','Number of processed items: '=>'Bilang ng mga na-prosesong item: ','Number of changed items: '=>'Bilang ng mga binagong item: ','WordPress Version'=>'Bersyon ng WordPress','Site URL'=>'URL ng Site','Home URL'=>'URL ng Tahanan','Active Theme'=>'Aktibong Tema','Version'=>'Bersyon','Checking...'=>'Nagre-repaso...','Show the Response'=>'Ipakita ang Tugon','passed'=>'nagawa','failed'=>'nabigo','Benchmarks'=>'Mga Benchmark','Cache'=>'Cache','Tag groups pro only'=>'Tag groups pro lamang','Server'=>'Server','Constants'=>'Mga Constants','Well done!'=>'Magaling!','Now go the Tag Group Administration.'=>'Ngayon ay pumunta sa Pamamahala ng Tag Group.','Or preview the sample page here.'=>'O i-preview ang sample na pahina dito.','Or go to the <a %1$s>Tag Groups settings</a> or visit the <a %2$s>documentation</a>.'=>'O pumunta sa <a %1$s>mga setting ng Tag Groups</a> o bisitahin ang <a %2$s>dokumento</a>.','Now go to the <a %1$s>Tag Groups settings</a>, or visit the <a %2$s>documentation</a>.'=>'Ngayon pumunta sa <a %1$s>mga setting ng Tag Groups</a>, o bisitahin ang <a %2$s>dokumento</a>.','If you need to launch the Setup Wizard again, you can find it in the settings. Just enter "wizard" in the search field.'=>'Kung kailangan mong ilunsad muli ang Setup Wizard, makikita mo ito sa mga setting. Ipasok lamang ang "wizard" sa search field.','Happy tagging!'=>'Masaya sa pag-tag!','Tag Groups Setup Wizard'=>'Tag Groups Setup Wizard','Now you are ready to create your own tag groups. If you prefer to start out from a sample, we will create for you three groups and three tags. You can play around with them, rename or delete them.'=>'Ngayon handa ka nang lumikha ng sarili mong tag groups. Kung mas gusto mong magsimula mula sa isang sample, lilikha kami para sa iyo ng tatlong grupo at tatlong tag. Maaari mong subukan ang mga ito, palitan ang pangalan o tanggalin ang mga ito.','Create sample groups:'=>'Lumikha ng mga sample na grupo:','Create sample tags in these groups:'=>'Lumikha ng mga sample na tag sa mga grupong ito:','Next Step'=>'Susunod na Hakbang','On the following pages we will guide you through the basic settings that you need for the most common features.'=>'Sa mga susunod na pahina, gagabayan ka namin sa mga pangunahing setting na kailangan mo para sa pinakakaraniwang mga tampok.','You can later make changes or fine-tune the details in the Tag Groups settings.'=>'Maaari mong baguhin o ayusin ang mga detalye sa Tag Groups settings sa ibang pagkakataon.','(show me the menu)'=>'(ipakita mo sa akin ang menu)','Feel free to abort the Setup Wizard any time and continue on your own path. You can also launch it again at a later time.'=>'Huwag mag-atubiling i-abort ang Setup Wizard anumang oras at ipagpatuloy ang iyong sariling landas. Maaari mo rin itong ilunsad muli sa ibang pagkakataon.','The wizard will offer more options after upgrading to premium.'=>'Magbibigay ang wizard ng higit pang mga opsyon pagkatapos mag-upgrade sa premium.','Choose the taxonomies for which you want to use tag groups.'=>'Pumili ng mga taxonomy na nais mong gamitin ang tag groups.','In most cases the default taxonomy <b>Tags (post_tag)</b> will do the job.'=>'Sa karamihan ng mga kaso, ang default na taxonomy <b>Tags (post_tag)</b> ay sapat na.','post type'=>'post type','You will find more options in the Tag Groups settings.'=>'Makikita mo ang higit pang mga opsyon sa Tag Groups settings.','Tag Group Administration'=>'Tag Group Administration','Filter by label'=>'I-filter ayon sa label','Tag Group name'=>'Pangalan ng Tag Group','Number of assigned tags'=>'Bilang ng naitalagang tag','Actions'=>'Mga Aksyon','Change order'=>'Baguhin ang pagkakasunud-sunod','Group ID'=>'ID ng Grupo','Edit'=>'I-edit','Create'=>'Lumikha','new'=>'bago','label'=>'label','Delete this group.'=>'Tanggalin ang grupong ito.','Create a new group below.'=>'Lumikha ng bagong grupo sa ibaba.','Add New Tag Group'=>'Magdagdag ng Bagong Grupo ng Tag','move up'=>'ilipat pataas','move down'=>'ilipat pababa','reload'=>'i-reload','next page'=>'susunod na pahina','previous page'=>'nakaraang pahina','go to page:'=>'pumunta sa pahina:','Show posts'=>'Ipakita ang mga post','Show tags'=>'Ipakita ang mga tag','Do you really want to delete this tag group?'=>'Talaga bang nais mong tanggalin ang grupong tag na ito?','Please visit <a %1$s>%2$s</a>.'=>'Pakisuyin ang <a %1$s>%2$s</a>.','Read more'=>'Magbasa pa','Thanks for using Tag Groups | %1$sTaxoPress.com%2$s | Version %3$s'=>'Salamat sa paggamit ng Tag Groups | %1$sTaxoPress.com%2$s | Bersyon %3$s','Assign to'=>'Itatalaga sa','Filter off'=>'I-off ang filter','Please select one of the languages above to see the correct tag groups!'=>'Pakisuyin ang isa sa mga wika sa itaas upang makita ang tamang mga tag group!','Groups'=>'Mga grupo']];